        return desconto.negate();
    }

    @Override
    public BigDecimal calcularValorParcela(BigDecimal totalPedido, int parcelas) {
        BigDecimal ajuste = calcularAjuste(totalPedido, parcelas);
        return totalPedido.add(ajuste);
    }
}

